package com.morongaming.forsakenrealm;
import android.graphics.*;import org.json.*;
final class ArmsIconPainter {
 private static final Paint p=new Paint(3);private static final ScenePainter scene=new ScenePainter();
 static boolean draw(Canvas c,JSONObject item,float x,float y,float size){if(item==null||(!item.optBoolean("blackpowder")&&!item.optBoolean("blackpowderAmmo")&&!item.optBoolean("siegeEngine")))return false;c.save();c.translate(x,y);c.scale(size/100,size/100);String id=item.optString("id");if(item.optBoolean("siegeEngine")){c.translate(50,92);c.scale(.72f,.72f);scene.structure(c,id,0,0);}else if(item.optBoolean("blackpowderAmmo")){String type=item.optString("ammoType");p.setColor(0xffb2a186);c.drawRoundRect(27,18,68,82,9,9,p);p.setShader(new LinearGradient(28,25,64,55,0xffd8d8ce,0xff4b4f51,Shader.TileMode.CLAMP));c.drawCircle(48,39,18,p);p.setShader(null);p.setColor(type.equals("fire")?0xffc76e32:type.equals("poison")?0xff729250:type.equals("bleeding")?0xffa54742:type.equals("armorPiercing")?0xff54869b:type.equals("explosive")?0xffd3ad51:0xff66543f);c.drawRect(27,62,68,72,p);}else{c.rotate(-24,50,50);p.setColor(0xff795132);c.drawRoundRect(7,49,52,63,4,4,p);Path stock=new Path();stock.moveTo(10,53);stock.lineTo(29,56);stock.lineTo(21,79);stock.lineTo(7,75);stock.close();c.drawPath(stock,p);p.setShader(new LinearGradient(0,39,0,54,0xffc2c6bd,0xff4b5151,Shader.TileMode.CLAMP));c.drawRect(36,39,id.equals("pistol")?72:95,51,p);p.setShader(null);p.setColor(0xffc9b88b);c.drawRect(35,43,42,58,p);if(id.equals("blunderbuss")){Path muzzle=new Path();muzzle.moveTo(83,39);muzzle.lineTo(97,32);muzzle.lineTo(97,59);muzzle.lineTo(83,51);muzzle.close();p.setColor(0xff919b91);c.drawPath(muzzle,p);}p.setColor(0xff302b23);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);c.drawOval(32,57,49,70,p);p.setStyle(Paint.Style.FILL);}c.restore();return true;}
}

